/* ═══ Perf #120/#121: Client-side gym data cache (sessionStorage) ═══
   Revisiting same area is instant, no refetch needed.
   Cache key = lat/lng rounded to 3 decimals (~111m precision). TTL = 10 min. */
const _gymCache={
  _key(lat,lng){return 'sg_gc_'+Math.round(lat*1000)+','+Math.round(lng*1000);},
  get(lat,lng){try{var k=this._key(lat,lng);var raw=sessionStorage.getItem(k);if(!raw)return null;var d=JSON.parse(raw);if(Date.now()-d.t>600000)return null;return d.g;}catch(e){return null;}},
  set(lat,lng,gyms){try{var k=this._key(lat,lng);sessionStorage.setItem(k,JSON.stringify({g:gyms,t:Date.now()}));}catch(e){}},
  getSearch(q){try{var raw=sessionStorage.getItem('sg_sc_'+q);if(!raw)return null;var d=JSON.parse(raw);if(Date.now()-d.t>600000)return null;return d.g;}catch(e){return null;}},
  setSearch(q,gyms){try{sessionStorage.setItem('sg_sc_'+q,JSON.stringify({g:gyms,t:Date.now()}));}catch(e){}}
};

/* ═══ Perf #121: Photo preloader (priority queue pattern) ═══
   Preload photos for the next 2 gym cards so swipe feels instant. */
const _photoPreloader={
  _loaded:new Set(),
  preload(urls){
    urls.forEach(function(u){
      if(!u||_photoPreloader._loaded.has(u))return;
      _photoPreloader._loaded.add(u);
      var img=new Image();
      img.decoding='async';
      img.src=u;
    });
  },
  preloadGyms(gyms,startIdx){
    var urls=[];
    for(var i=startIdx;i<Math.min(startIdx+3,gyms.length);i++){
      var g=gyms[i];if(!g)continue;
      var p=_gymPhotoUrl(g);
      if(p)urls.push(p);
    }
    if(urls.length)_photoPreloader.preload(urls);
  }
};

/* ═══ Perf Round 2: Touch-start prefetch  ═══
   Start loading gym detail data on touchstart — 150-300ms head start before tap fires.
   When showBookingCheckout() runs, the /api/live/place data is already cached by browser. */
var _touchPrefetchDone={};
document.addEventListener('touchstart',function(e){
  var el=e.target.closest('[data-gym-id]');
  if(!el)return;
  var id=el.getAttribute('data-gym-id');
  if(id&&!_touchPrefetchDone[id]){
    _touchPrefetchDone[id]=true;
    fetch('/api/live/place/'+id).catch(function(){});
  }
},{passive:true});

/* ═══ Perf Round 2: Connection-aware photo sizes (streaming-app technique) ═══
   On slow 2G/3G, use 400px photos instead of 600px — 40% less data. */
var _photoMaxWidth=600;
if(navigator.connection){
  var _ct=navigator.connection.effectiveType;
  if(_ct==='slow-2g'||_ct==='2g'||_ct==='3g')_photoMaxWidth=400;
  navigator.connection.addEventListener('change',function(){
    var ct2=navigator.connection.effectiveType;
    _photoMaxWidth=(ct2==='slow-2g'||ct2==='2g'||ct2==='3g')?400:600;
  });
}
/* Helper: get photo URL with connection-aware size */
function _gymPhotoUrl(gym,size){
  var w=size||_photoMaxWidth;
  return gym.photo||gym.photo_url||
    (gym.photoReference?'/api/photo?ref='+encodeURIComponent(gym.photoReference)+'&maxwidth='+w:
    (gym.photo_reference?'/api/photo?ref='+encodeURIComponent(gym.photo_reference)+'&maxwidth='+w:''));
}

/* ═══ Perf Round 2: requestIdleCallback for non-critical work ═══ */
var _scheduleIdle=window.requestIdleCallback||function(cb){setTimeout(cb,50);};

/* ═══ Perf v2: rAF-throttled scroll handler  ═══
 * Scroll events fire 60-120x/sec. Without throttle, every pixel triggers DOM reads
 * (offsetWidth, scrollLeft) + writes (classList, textContent), causing layout thrashing.
 * This wraps a scroll callback so it fires at most once per animation frame (~16ms). */
function _throttledScroll(fn){
  var ticking=false;
  return function(){
    if(ticking)return;
    ticking=true;
    requestAnimationFrame(function(){ticking=false;fn();});
  };
}

/* ═══ Perf v2: IntersectionObserver for off-screen animation pause ═══
 * casinoGlow box-shadow animation causes constant GPU repaints on EVERY CTA button.
 * Pause animations on off-screen elements to save battery + GPU.
 * This observer adds/removes 'tt-offscreen' class to pause animations. */
var _visibilityObserver=('IntersectionObserver' in window)?new IntersectionObserver(function(entries){
  entries.forEach(function(e){
    if(e.isIntersecting){
      e.target.classList.remove('tt-offscreen');
      /* Perf v3: Load deferred photos when card enters viewport.
       * Replaces data-bg with background-image on first intersection. */
      var deferred=e.target.querySelectorAll('[data-bg]');
      if(deferred.length){
        deferred.forEach(function(el){
          el.style.backgroundImage='url('+el.getAttribute('data-bg')+')';
          el.removeAttribute('data-bg');
        });
      }
      /* Perf v5: Pre-fetch gym data when card enters viewport for instant overlay */
      var gid=e.target.getAttribute('data-gym-id');
      if(gid&&window._gymDataCache&&!window._gymDataCache[gid]){
        try{api.getLive('/place/'+gid).then(function(data){
          if(data&&data.gym){
            var _oh=data.openingHours||{};
            if(data.gym.ownerIsOpen===true)_oh.isOpen=true;
            else if(data.gym.ownerIsOpen===false)_oh.isOpen=false;
            window._gymDataCache[gid]={data:{...data.gym,id:data.gym.dbId||data.gym.placeId,place_id:data.gym.placeId,photo_url:data.photos?.[0]?.url||null,photos_list:data.photos||[],rating:data.rating?.google||null,user_ratings_total:data.rating?.googleTotal||0,formatted_address:data.gym.address,vicinity:data.gym.address,opening_hours:_oh,openNow:_oh.isOpen??null,reviews_data:data.reviews,pricing:data.pricing,map:data.map,source:'live'},ts:Date.now()};
          }
        }).catch(function(){});}catch(err){}
      }
    }
    else{e.target.classList.add('tt-offscreen');}
  });
},{rootMargin:'600px',threshold:0}):null;

