// ─── 3-Tab Navigation System ───
function getTabForRoute(path){
  if(path==='/'||path==='')return 'reels';
  if(path==='/reels')return 'reels';
  if(path==='/explore'||path==='/nearby'||path==='/search'||path.startsWith('/gym/')||path==='/booking-success'||path.startsWith('/r/')||path==='/checkout')return 'book';
  if(path==='/music')return 'music';
  if(path==='/photos'||path==='/carousel')return 'photos';
  if(path==='/chat'||path==='/community')return 'chat';
  if(path==='/ai-trainer'||path==='/trainer')return 'trainer';
  if(path==='/creator'||path==='/creator/')return 'creator';
  if(path==='/partner'||path==='/partner/'||path.startsWith('/partner/'))return 'partner';
  return 'more';
}
function switchTab(tab){
  state.activeTab=tab;
  if(tab==='reels'){state.route='/';history.pushState(null,'','/');}
  else if(tab==='book'){state.route=state._lastBookRoute||'/explore';history.pushState(null,'',state.route);}
  else if(tab==='music'){state.route='/music';history.pushState(null,'','/music');}
  else if(tab==='photos'){state.route='/photos';history.pushState(null,'','/photos');}
  else if(tab==='chat'){state.route='/chat';history.pushState(null,'','/chat');}
  else if(tab==='trainer'){state.route='/ai-trainer';history.pushState(null,'','/ai-trainer');}
  else if(tab==='creator'){state.route='/creator';history.pushState(null,'','/creator');}
  else if(tab==='partner'){state.route='/partner';history.pushState(null,'','/partner');}
  else if(tab==='more'){state.route=state._lastMoreRoute||'/more';history.pushState(null,'',state.route);}
  render();
  // ── Bug Fix: Toggle persistent reels iframe visibility ──
  _syncReelsVisibility();
  // ── Bug Fix: Force pointer-events restore on Book/More tab ──
  if(tab!=='reels'){
    var _appEl=document.getElementById('app');if(_appEl)_appEl.style.pointerEvents='';
    var _rwrap=document.getElementById('sg-reels-persistent');
    if(_rwrap){_rwrap.style.display='none';_rwrap.style.zIndex='-1';}
  }
  var _sc=document.querySelector('.sg-tab-content');if(_sc)_sc.scrollTop=0;
}
// ── Persistent Reels Iframe: keep alive outside #app, toggle display ──
function _ensureReelsIframe(){
  if(document.getElementById('sg-reels-persistent'))return;
  var wrap=document.createElement('div');
  wrap.id='sg-reels-persistent';
  var showNow=state.activeTab==='reels';
  wrap.style.cssText='position:fixed;top:0;left:0;right:0;bottom:calc(56px + env(safe-area-inset-bottom, 0px));z-index:'+(showNow?'8000':'1')+';background:#000;display:'+(showNow?'block':'none')+';';
  wrap.innerHTML='<iframe id="sg-reels-iframe" title="ScanGym Reels" src="/reels/" style="position:absolute;top:0;left:0;width:100%;height:100%;border:none;z-index:1;" allow="autoplay; fullscreen"></iframe>'
    +'<div id="sg-reels-fallback" style="display:none;position:absolute;top:0;left:0;right:0;bottom:0;z-index:2;background:linear-gradient(180deg,#0a0a16 0%,#111127 100%);flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:20px;">'
    +'<div style="font-size:64px;margin-bottom:16px;">🎬</div>'
    +'<p style="color:#fff;font-size:22px;font-weight:800;margin:0 0 8px;">Reels Coming Soon</p>'
    +'<p style="color:rgba(255,255,255,.45);font-size:14px;margin:0 0 24px;max-width:280px;">Gym workout videos, tips, and inspiration from creators worldwide.</p>'
    +'<button onclick="switchTab(\'book\')" style="background:#FF6D00;color:#fff;font-weight:700;font-size:15px;padding:14px 32px;border-radius:14px;border:none;cursor:pointer;box-shadow:0 4px 20px rgba(255,109,0,.3);">🏋️ Find a Gym Instead</button>'
    +'</div>';
  document.body.appendChild(wrap);
}
function _syncReelsVisibility(){
  var wrap=document.getElementById('sg-reels-persistent');
  if(state.activeTab==='reels'){
    if(!wrap)_ensureReelsIframe();
    wrap=document.getElementById('sg-reels-persistent');
    if(wrap){wrap.style.display='block';wrap.style.zIndex='8000';}
    // FIX #1: Make #app transparent to touch events when reels are active
    // so touches pass through to the reels iframe underneath. The tab bar
    // (z-index:9000) stays above and keeps pointer-events.
    var appEl=document.getElementById('app');
    if(appEl)appEl.style.pointerEvents='none';
    var tabBar=document.querySelector('.sg-tab-bar');
    if(tabBar)tabBar.style.pointerEvents='auto';
    // FIX C2: Tell reels iframe to resume playback
    _sendToReels({type:'sg-reels-visibility',visible:true});
  }else{
    // FIX C2: Tell reels iframe to pause before hiding
    _sendToReels({type:'sg-reels-visibility',visible:false});
    if(wrap){wrap.style.display='none';wrap.style.zIndex='-1';}
    var appEl=document.getElementById('app');
    if(appEl)appEl.style.pointerEvents='';
  }
}
function navigate(path,pushState=true){
  // Fix: separate pathname from query string so route matching works
  var qIdx=path.indexOf('?');
  var pathname=qIdx>=0?path.substring(0,qIdx):path;
  state.route=pathname;
  state.routeQuery=qIdx>=0?path.substring(qIdx):'';
  state.activeTab=getTabForRoute(pathname);
  // Remember last route per tab for back-navigation
  if(state.activeTab==='book')state._lastBookRoute=path;
  else if(state.activeTab==='more')state._lastMoreRoute=path;
  if(pushState)history.pushState(null,'',pathname+(state.routeQuery||''));
  render();
  _syncReelsVisibility();
  var _sc=document.querySelector('.sg-tab-content');if(_sc)_sc.scrollTop=0;
}
window.addEventListener('popstate',()=>{state.route=location.pathname;state.routeQuery=location.search||'';state.activeTab=getTabForRoute(state.route);render();_syncReelsVisibility();});

// #171 fix: Capture ?ref= URL param on ANY page load (not just /r/{handle})
// Amazon-style: also capture &src= for multi-channel tracking + &gym= for gym deep links
(function(){
  try{
    var params=new URLSearchParams(window.location.search);
    var ref=params.get('ref');
    if(ref){
      var src=params.get('src')||null;
      var gymDeepLink=params.get('gym')||null;
      var expiry=Date.now()+(30*24*60*60*1000);
      localStorage.setItem('sg_referral',JSON.stringify({handle:ref,expiry:expiry,source:src,gymId:gymDeepLink}));
      document.cookie='sg_referral='+encodeURIComponent(ref)+';path=/;max-age='+(30*24*60*60)+';SameSite=Lax';
      // Track click server-side with source channel + gym
      fetch('/api/referrals/track',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creatorHandle:ref,visitorSession:Date.now().toString(36),source:src,gymId:gymDeepLink})}).catch(function(){});
      // Clean tracking params from URL without reload
      params.delete('ref');params.delete('src');params.delete('gym');
      var clean=window.location.pathname+(params.toString()?'?'+params.toString():'');
      history.replaceState(null,'',clean);
      // If gym deep link, navigate to that gym after a moment
      if(gymDeepLink){setTimeout(function(){if(typeof navigate==='function')navigate('/gym/'+gymDeepLink);},500);}
    }
  }catch(e){}
})();

