window._ovPayAddCard=async function(){
  if(!state.user){
    _showToast('Please sign in first to save a card');
    setTimeout(function(){navigate('/login');},1200);
    return;
  }
  const form=document.getElementById('ov-pay-card-form');
  const btn=document.getElementById('ov-pay-add-btn');
  if(!form)return;
  form.style.display='block';
  if(btn)btn.style.display='none';
  // Ensure Stripe.js is loaded before mounting elements
  await ensureStripeLoaded();
  if(!window._ovPayStripeElements&&window.Stripe){
    const stripeKey=window._stripePublicKey||STRIPE_PK||'pk_live_placeholder';
    const si=Stripe(stripeKey);
    window._ovPayStripeInstance=si;
    const elStyle={base:{fontSize:'16px',color:'#1a1a2e',fontWeight:'400',fontFamily:'-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif','::placeholder':{color:'#9ca3af'}},invalid:{color:'#ef4444'}};
    window._ovPayStripeElements=si.elements({
      appearance:{theme:'flat',variables:{colorPrimary:'#22c55e',colorBackground:'#ffffff',colorText:'#1a1a2e',colorTextPlaceholder:'#9ca3af',borderRadius:'0px',colorDanger:'#ef4444'}},
    });
    // Separate fields layout
    window._ovPayCardNumber=window._ovPayStripeElements.create('cardNumber',{style:elStyle,showIcon:true});
    window._ovPayCardExpiry=window._ovPayStripeElements.create('cardExpiry',{style:elStyle});
    window._ovPayCardCvc=window._ovPayStripeElements.create('cardCvc',{style:elStyle});
    window._ovPayCardNumber.mount('#ov-pay-card-number');
    window._ovPayCardExpiry.mount('#ov-pay-card-expiry');
    window._ovPayCardCvc.mount('#ov-pay-card-cvc');
    // Track completion of all 3 fields
    window._ovPayFieldState={number:false,expiry:false,cvc:false};
    function _ovPayCheckComplete(){
      const fs=window._ovPayFieldState;
      const saveBtn=document.getElementById('ov-pay-save-btn');
      if(saveBtn){
        if(fs.number&&fs.expiry&&fs.cvc){saveBtn.style.opacity='1';saveBtn.style.pointerEvents='auto';}
        else{saveBtn.style.opacity='.5';saveBtn.style.pointerEvents='none';}
      }
    }
    function _ovPayHandleErr(ev){
      const errEl=document.getElementById('ov-pay-card-error');
      if(errEl){
        if(ev.error){errEl.textContent=ev.error.message;errEl.style.display='block';}
        else{errEl.style.display='none';}
      }
    }
    // Fix 5: Card brand detection icon
    window._ovPayCardNumber.on('change',function(ev){
      window._ovPayFieldState.number=ev.complete;_ovPayCheckComplete();_ovPayHandleErr(ev);
      const badge=document.getElementById('ov-pay-brand-badge');
      if(badge){
        const brandMap={visa:'Visa',mastercard:'Mastercard',amex:'Amex',discover:'Discover',diners:'Diners',jcb:'JCB',unionpay:'UnionPay'};
        const brandColors={visa:'#1a1f71',mastercard:'#eb001b',amex:'#006fcf',discover:'#ff6000'};
        if(ev.brand&&ev.brand!=='unknown'){
          badge.textContent=brandMap[ev.brand]||ev.brand;
          badge.style.background=brandColors[ev.brand]||'#334155';
          badge.style.color='#fff';
        }else{
          badge.textContent='';badge.style.background='#f1f5f9';badge.style.color='#64748b';
        }
      }
    });
    window._ovPayCardExpiry.on('change',function(ev){window._ovPayFieldState.expiry=ev.complete;_ovPayCheckComplete();_ovPayHandleErr(ev);});
    window._ovPayCardCvc.on('change',function(ev){window._ovPayFieldState.cvc=ev.complete;_ovPayCheckComplete();_ovPayHandleErr(ev);});
    // Reference for confirmCardSetup — use cardNumber element
    window._ovPayCardElement=window._ovPayCardNumber;
  }
};

window._ovPayCloseCardForm=function(){
  const form=document.getElementById('ov-pay-card-form');
  const btn=document.getElementById('ov-pay-add-btn');
  if(form)form.style.display='none';
  if(btn)btn.style.display='flex';
};

window._ovPaySaveCard=async function(){
  const saveBtn=document.getElementById('ov-pay-save-btn');
  const errEl=document.getElementById('ov-pay-card-error');
  if(!window._ovPayStripeInstance||!window._ovPayCardElement)return;
  if(saveBtn){saveBtn.textContent='Saving…';saveBtn.style.opacity='.6';saveBtn.style.pointerEvents='none';}
  try{
    const siResp=await fetch('/api/payment/setup-card',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'}});
    const siData=await siResp.json();
    if(!siData.clientSecret)throw new Error(siData.error||'Failed to create setup');
    // Include billing details (country, postcode, nickname)
    const _payCountry=(document.getElementById('ov-pay-country')||{}).value||'GB';
    const _payPostcode=(document.getElementById('ov-pay-postcode')||{}).value||'';
    const _payNickname=(document.getElementById('ov-pay-nickname')||{}).value||'';
    const{setupIntent,error}=await window._ovPayStripeInstance.confirmCardSetup(siData.clientSecret,{
      payment_method:{card:window._ovPayCardElement,billing_details:{address:{country:_payCountry,postal_code:_payPostcode}}},
    });
    if(error)throw new Error(error.message);
    await fetch('/api/payment/confirm-setup',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({setupIntentId:setupIntent.id})});
    _ovPayCloseCardForm();
    if(window._ovPayCardNumber){window._ovPayCardNumber.clear();window._ovPayCardExpiry.clear();window._ovPayCardCvc.clear();}
    _showToast('💳 Card saved successfully!');
    await _ovPayLoadCards();
    // ═══ Auto-continue to checkout if booking was pending ═══
    if(window._pendingCheckout){
      const pc=window._pendingCheckout;
      window._pendingCheckout=null;
      try{
        const freshCards=await fetch('/api/payment/saved-cards',{credentials:'include'}).then(r=>r.json());
        if(freshCards.cards&&freshCards.cards.length>0){
          const defCard=freshCards.cards.find(c=>c.isDefault)||freshCards.cards[0];
          window._gymBookingState=window._gymBookingState||{};
          window._gymBookingState.paymentMethod='saved';
          window._gymBookingState.savedCard={id:defCard.id,brand:defCard.brand,last4:defCard.last4};
        }
      }catch(e){}
      closeGymOverlay();
      setTimeout(()=>showBookingCheckout(pc.gymId,pc.prefillDate,pc.prefillTime),200);
      return;
    }
  }catch(err){
    if(errEl){errEl.textContent=err.message;errEl.style.display='block';}
  }finally{
    if(saveBtn){saveBtn.textContent='Save Card';saveBtn.style.opacity='1';saveBtn.style.pointerEvents='auto';}
  }
};

window._ovPaySetDefault=async function(cardId){
  try{
    await fetch('/api/payment/set-default-card',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({cardId})});
    _showToast('✅ Default card updated');
    _ovPayLoadCards();
  }catch(err){_showToast('Failed to update default card');}
};

window._ovPayDeleteCard=async function(cardId,label){
  if(!confirm('Remove '+label+'?'))return;
  try{
    await fetch('/api/payment/saved-cards/'+cardId,{method:'DELETE',credentials:'include'});
    _showToast('Card removed');
    _ovPayLoadCards();
  }catch(err){_showToast('Failed to remove card');}
};

