window._updateDateCTA=function(){
  var st=window._datePickerState||{};
  var btn=document.getElementById('sg-date-cta');
  if(!btn)return;
  if(!st.selectedTime){btn.textContent='Select a time';btn.style.opacity='.5';return;}
  btn.style.opacity='1';
  var passNames={day:'Day Pass','3day':'3-Day Pass',weekly:'Weekly Pass',monthly:'Monthly Pass'};
  var passName=passNames[st.selectedPass||'day']||'Day Pass';
  var parts=(st.selectedTime||'').split(':');
  var h=parseInt(parts[0])||0;var m=parts[1]||'00';
  var ampm=h>=12?'PM':'AM';var h12=h%12||12;
  var timeStr=h12+':'+m+' '+ampm;
  var idx2=st.selectedIdx||0;
  var dateLabel=idx2===0?'Today':idx2===1?'Tomorrow':'';
  if(!dateLabel){
    var dd=new Date();dd.setDate(dd.getDate()+idx2);
    var mn=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    dateLabel=dd.getDate()+' '+mn[dd.getMonth()];
  }
  var modeVerb=window._calMode==='leave'?'Leave by':'Arrive by';
  btn.textContent=modeVerb+' '+timeStr+' \u00b7 '+dateLabel+' \u00b7 '+passName;
};

window.openDateSheet=function(){
  const sheet=document.getElementById('gym-date-sheet');
  if(!sheet)return;
  // Reset state
  window._datePickerState.selectedDateIdx=0;
  // FIX #8: Default = today pre-selected with next-hour time slot
  var _now8=new Date();
  var _nextHourMin8=Math.ceil((_now8.getHours()*60+_now8.getMinutes())/60)*60; // Round up to next hour
  if(_nextHourMin8>22*60)_nextHourMin8=22*60; // Cap at 10pm
  if(_nextHourMin8<6*60)_nextHourMin8=6*60; // Floor at 6am
  var _hh8=String(Math.floor(_nextHourMin8/60)).padStart(2,'0');
  var _mm8=String(_nextHourMin8%60).padStart(2,'0');
  window._datePickerState.selectedTime=_hh8+':'+_mm8;
  window._gymSelectedTime=_hh8+':'+_mm8;
  // Set today's date
  window._gymBookingState.selectedDate=new Date().toISOString().split('T')[0];
  // Build UI
  window._buildDateStrip();
  window._calCurrentMonth=new Date().getMonth();window._calCurrentYear=new Date().getFullYear();window._calSelectedDate=new Date();window._buildMonthGrid();
  window._buildTimeList(0);
  // Open
  sheet.classList.add('open');
  // ── Bug Fix #3: Hide tab bar so it can't cover the CTA ──
  var _dtTabBar=document.querySelector('.sg-tab-bar');if(_dtTabBar)_dtTabBar.classList.add('hidden');
  // ── Bug Fix #3: Explicit touch handler on Confirm time button for mobile ──
  var _dtCta=document.getElementById('sg-date-cta');
  if(_dtCta&&!_dtCta._touchFixed){
    _dtCta._touchFixed=true;
    var _dtTapStart=0;
    _dtCta.addEventListener('touchstart',function(){_dtTapStart=Date.now();},{passive:true});
    _dtCta.addEventListener('touchend',function(e){
      if(Date.now()-_dtTapStart<300){e.preventDefault();confirmDateSheet();}
    },{passive:false});
  }
};

