// ─── Google One Tap + Sign-In Handler (upgraded from Fix #5B) ───
// Shared callback for both One Tap auto-prompt and manual button click
window._sgGoogleCallback=async function(response){
  try{
    const r=await fetch('/api/auth/google-login',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      credentials:'include',
      body:JSON.stringify({credential:response.credential})
    });
    const data=await r.json();
    if(data.success&&data.user){
      state.user=data.user;
      state.authStep='phone';
      // If auth sheet is open, advance to next step (card/withdraw)
      if(typeof window._sgAuthAfterSuccess==='function'&&document.querySelector('.sg-auth-overlay.open')){
        window._sgAuthAfterSuccess();
      }else{
        _sendToReels({type:'sg-auth-state',loggedIn:true,user:{name:data.user.name,phone:data.user.phone}});
        sgToast('Welcome, '+(data.user.name||'there')+'! 🎉','success',3000);
        if(window._pendingCheckout&&window._pendingCheckout.gymId){
          const pc=window._pendingCheckout;
          window._pendingCheckout=null;
          if(state.activeTab!=='book')navigate('/explore');
          setTimeout(()=>showBookingCheckout(pc.gymId,pc.prefillDate,pc.prefillTime),200);
        }else if(window._pendingReelsAction){
          _sendToReels({type:'sg-auth-complete',action:window._pendingReelsAction,video:window._pendingReelsVideo});
          window._pendingReelsAction=null;window._pendingReelsVideo=null;
        }else if(window._sgOneTapCreatorMode){
          window._sgOneTapCreatorMode=false;
          _handleCreatorGoogleSignup(data.user);
        }else{
          navigate('/explore');
        }
      }
    }else{
      sgToast(data.error||'Google sign-in failed','error',3000);
    }
  }catch(e){
    sgToast('Google sign-in error: '+e.message,'error',3000);
  }
  const btn=document.getElementById('google-signin-btn');
  if(btn){btn.disabled=false;btn.style.opacity='1';}
};

// Load Google Identity Services library once
window._sgLoadGIS=function(){
  return new Promise(function(resolve,reject){
    if(window.google&&window.google.accounts){resolve();return;}
    if(window._sgGISLoading){window._sgGISLoading.then(resolve).catch(reject);return;}
    window._sgGISLoading=new Promise(function(res,rej){
      var s=document.createElement('script');
      s.src='https://accounts.google.com/gsi/client';
      s.onload=function(){res();resolve();};
      s.onerror=function(){rej();reject();};
      document.head.appendChild(s);
    });
  });
};

// Initialize Google One Tap (auto-prompts on any page if user is not logged in)
window._sgInitOneTap=async function(){
  if(state.user)return; // already logged in
  try{
    await window._sgLoadGIS();
    google.accounts.id.initialize({
      client_id:window._sgGoogleClientId||'placeholder-client-id.apps.googleusercontent.com',
      callback:window._sgGoogleCallback,
      auto_select:true,
      cancel_on_tap_outside:false,
      itp_support:true
    });
    google.accounts.id.prompt(); // Show One Tap overlay automatically
  }catch(e){
    console.log('[OneTap] Could not initialize:',e.message);
  }
};

// R3: One Tap deferred until first user interaction — was firing on page load,
// loading Google's gsi/client (403 on load) + showing an intrusive auto-prompt.
// The 'Continue with Google' button flow is unchanged.
(function(){var _fired=false;function _go(){if(_fired)return;_fired=true;setTimeout(function(){window._sgInitOneTap&&window._sgInitOneTap();},300);}
['pointerdown','touchstart','keydown','scroll'].forEach(function(ev){document.addEventListener(ev,_go,{once:true,passive:true,capture:true});});})();

// Manual Google Sign-In button handler — uses OAuth token flow (reliable popup)
// FIX: Replaced prompt() (One Tap) with initTokenClient().requestAccessToken()
// One Tap frequently fails on mobile due to: cooldowns after dismiss, 3rd-party
// cookie blocks, incognito mode, and browser restrictions. The OAuth token client
// opens a proper Google consent popup that works reliably everywhere.
window.handleGoogleSignIn=async function(){
  const btn=document.getElementById('google-signin-btn');
  if(btn){btn.disabled=true;btn.style.opacity='.6';}
  try{
    await window._sgLoadGIS();
    var tokenClient=google.accounts.oauth2.initTokenClient({
      client_id:window._sgGoogleClientId||'placeholder-client-id.apps.googleusercontent.com',
      scope:'openid email profile',
      callback:async function(tokenResponse){
        if(tokenResponse.error){
          sgToast('Google sign-in cancelled','info',2000);
          if(btn){btn.disabled=false;btn.style.opacity='1';}
          return;
        }
        try{
          var r=await fetch('/api/auth/google-token-login',{
            method:'POST',
            headers:{'Content-Type':'application/json'},
            credentials:'include',
            body:JSON.stringify({access_token:tokenResponse.access_token})
          });
          var data=await r.json();
          if(data.success&&data.user){
            state.user=data.user;
            state.authStep='phone';
            if(typeof window._sgAuthAfterSuccess==='function'&&document.querySelector('.sg-auth-overlay.open')){
              window._sgAuthAfterSuccess();
            }else{
              _sendToReels({type:'sg-auth-state',loggedIn:true,user:{name:data.user.name,phone:data.user.phone}});
              sgToast('Welcome, '+(data.user.name||'there')+'! \ud83c\udf89','success',3000);
              if(window._pendingCheckout&&window._pendingCheckout.gymId){
                var pc=window._pendingCheckout;
                window._pendingCheckout=null;
                if(state.activeTab!=='book')navigate('/explore');
                setTimeout(function(){showBookingCheckout(pc.gymId,pc.prefillDate,pc.prefillTime);},80);
              }else if(window._pendingReelsAction){
                _sendToReels({type:'sg-auth-complete',action:window._pendingReelsAction,video:window._pendingReelsVideo});
                window._pendingReelsAction=null;window._pendingReelsVideo=null;
              }else if(window._sgOneTapCreatorMode){
                window._sgOneTapCreatorMode=false;
                _handleCreatorGoogleSignup(data.user);
              }else{
                navigate('/explore');
              }
            }
          }else{
            sgToast(data.error||'Google sign-in failed','error',3000);
          }
        }catch(e){
          sgToast('Google sign-in error: '+e.message,'error',3000);
        }
        if(btn){btn.disabled=false;btn.style.opacity='1';}
      }
    });
    tokenClient.requestAccessToken();
  }catch(e){
    sgToast('Could not load Google Sign-In: '+e.message,'error',3000);
    if(btn){btn.disabled=false;btn.style.opacity='1';}
  }
};

// ─── Apple Sign-In Handler ───
// Load Apple JS SDK once
window._sgLoadAppleJS=function(){
  return new Promise(function(resolve,reject){
    if(window.AppleID){resolve();return;}
    if(window._sgAppleLoading){window._sgAppleLoading.then(resolve).catch(reject);return;}
    window._sgAppleLoading=new Promise(function(res,rej){
      var s=document.createElement('script');
      s.src='https://appleid.cdn-apple.com/appleauth/static/jsapi/appleid/1/en_US/appleid.auth.js';
      s.onload=function(){res();resolve();};
      s.onerror=function(){rej(new Error('Failed to load Apple SDK'));reject(new Error('Failed to load Apple SDK'));};
      document.head.appendChild(s);
    });
  });
};

window.handleAppleSignIn=async function(){
  var btn=document.getElementById('apple-signin-btn');
  if(btn){btn.style.opacity='.6';btn.style.pointerEvents='none';}
  try{
    await window._sgLoadAppleJS();
    AppleID.auth.init({
      clientId:window._sgAppleClientId||'com.scangym.web',
      scope:'name email',
      redirectURI:window.location.origin+'/api/auth/apple-callback',
      usePopup:true
    });
    var data=await AppleID.auth.signIn();
    // data.authorization.id_token (JWT), data.authorization.code
    // data.user (only on FIRST sign-in: {name:{firstName,lastName}, email})
    var r=await fetch('/api/auth/apple-login',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      credentials:'include',
      body:JSON.stringify({
        id_token:data.authorization.id_token,
        code:data.authorization.code,
        user:data.user||null
      })
    });
    var result=await r.json();
    if(result.success&&result.user){
      state.user=result.user;
      state.authStep='phone';
      if(typeof window._sgAuthAfterSuccess==='function'&&document.querySelector('.sg-auth-overlay.open')){
        window._sgAuthAfterSuccess();
      }else{
        _sendToReels({type:'sg-auth-state',loggedIn:true,user:{name:result.user.name,phone:result.user.phone}});
        sgToast('Welcome, '+(result.user.name||'there')+'! \ud83c\udf89','success',3000);
        if(window._pendingCheckout&&window._pendingCheckout.gymId){
          var pc=window._pendingCheckout;
          window._pendingCheckout=null;
          if(state.activeTab!=='book')navigate('/explore');
          setTimeout(function(){showBookingCheckout(pc.gymId,pc.prefillDate,pc.prefillTime);},200);
        }else if(window._pendingReelsAction){
          _sendToReels({type:'sg-auth-complete',action:window._pendingReelsAction,video:window._pendingReelsVideo});
          window._pendingReelsAction=null;window._pendingReelsVideo=null;
        }else{
          navigate('/explore');
        }
      }
    }else{
      sgToast(result.error||'Apple sign-in failed','error',3000);
    }
  }catch(e){
    if(e&&e.error==='popup_closed_by_user'){
      sgToast('Apple sign-in cancelled','info',2000);
    }else{
      sgToast('Could not complete Apple sign-in','error',3000);
      console.error('[Apple Sign-In]',e);
    }
  }
  if(btn){btn.style.opacity='1';btn.style.pointerEvents='auto';}
};

