// ─── Auth Handlers ───
window.handleSendCode=async function(){
  const phoneInput=document.getElementById('auth-phone');
  const btn=document.getElementById('auth-btn');
  const errDiv=document.getElementById('auth-error');
  if(!phoneInput)return;
  const phone=phoneInput.value.replace(/\s/g,'');
  if(!phone||phone.length<10){
    errDiv.textContent='Please enter a valid phone number';errDiv.classList.remove('hidden');return;
  }
  btn.textContent='Sending...';btn.disabled=true;
  errDiv.classList.add('hidden');
  try{
    const countryCode=document.getElementById('auth-country-code')?.value||'+44';
    const fullPhone=phone.startsWith('+') ? phone : countryCode+phone.replace(/^0/,'');
    const r=await api.authPost('/send-code',{phone:fullPhone});
    if(r.success){
      state.authPhone=r.phone||fullPhone;
      state.authStep='code';
      render();
    }else{
      errDiv.textContent=(r.error||'Failed to send code')+' — Try "Continue with Google" below instead';errDiv.classList.remove('hidden');
      btn.textContent='Send Verification Code';btn.disabled=false;
    }
  }catch(e){
    errDiv.textContent='Network error — try again';errDiv.classList.remove('hidden');
    btn.textContent='Send Verification Code';btn.disabled=false;
  }
};

window.handleVerifyCode=async function(){
  const codeInput=document.getElementById('auth-code');
  const btn=document.getElementById('auth-btn');
  const errDiv=document.getElementById('auth-error');
  if(!codeInput)return;
  const code=codeInput.value.trim();
  if(!code||code.length<4){
    errDiv.textContent='Please enter the verification code';errDiv.classList.remove('hidden');return;
  }
  btn.textContent='Verifying...';btn.disabled=true;
  errDiv.classList.add('hidden');
  try{
    const r=await api.authPost('/verify',{phone:state.authPhone,code});
    if(r.success&&r.user){
      state.user=r.user;
      state.authStep='phone';
      if(typeof window._sgAuthAfterSuccess==='function'&&document.querySelector('.sg-auth-overlay.open')){
        window._sgAuthAfterSuccess();
      }else{
        if(typeof _sendToReels==='function')_sendToReels({type:'sg-auth-state',loggedIn:true,user:{name:r.user.name,phone:r.user.phone}});
        // Resume pending booking if user was trying to book before login
        if(window._pendingCheckout&&window._pendingCheckout.gymId){
          const pc=window._pendingCheckout;
          window._pendingCheckout=null;
          if(state.activeTab!=='book')navigate('/explore');
          setTimeout(()=>showBookingCheckout(pc.gymId,pc.prefillDate,pc.prefillTime),200);
        }else if(window._pendingReelsAction){
          if(typeof _sendToReels==='function')_sendToReels({type:'sg-auth-complete',action:window._pendingReelsAction,video:window._pendingReelsVideo});
          window._pendingReelsAction=null;window._pendingReelsVideo=null;
        }else if(state.pendingBookGym){
          navigate('/gym/'+state.pendingBookGym);
          state.pendingBookGym=null;
        }else{
          navigate('/explore');
        }
      }
    }else{
      errDiv.textContent=r.error||'Invalid code';errDiv.classList.remove('hidden');
      btn.textContent='Verify & Log In';btn.disabled=false;
    }
  }catch(e){
    errDiv.textContent='Network error — try again';errDiv.classList.remove('hidden');
    btn.textContent='Verify & Log In';btn.disabled=false;
  }
};

window.handleLogout=async function(){
  await api.authPost('/logout',{});
  state.user=null;
  navigate('/');
};

// ─── Booking Handler (ONE tap → ONE screen → DONE) ───
window.handleBookNow=async function(gymId){
  // Grab sidebar date/time if the user already selected them (desktop)
  const dateInput=document.querySelector('.sticky input[type="date"]');
  const timeSelect=document.querySelector('.sticky select');
  const date=dateInput?dateInput.value:'';
  const time=timeSelect?timeSelect.value:'';
  showBookingCheckout(gymId, date||undefined, time||undefined);
};



