// Owner toggle handler
window.sgOwnerToggle=async function(isOpen){
  const status=document.getElementById('sg-toggle-status');
  const knob=document.getElementById('sg-toggle-knob');
  if(knob) knob.style.transform=isOpen?'translateX(24px)':'translateX(0)';
  if(knob) knob.parentElement.previousElementSibling.style.background=isOpen?'#22c55e':'rgba(255,255,255,.15)';
  if(status){
    status.style.background=isOpen?'rgba(34,197,94,.1)':'rgba(239,68,68,.1)';
    status.style.borderColor=isOpen?'rgba(34,197,94,.15)':'rgba(239,68,68,.15)';
    status.style.color=isOpen?'#4ade80':'#f87171';
    status.textContent=isOpen?'✅ Your gym is currently accepting bookings':'❌ Your gym is currently closed for bookings';
  }
  try{
    // #88: Use new gym-partner 1-click toggle API
    const _gid=await window._sgResolvePartnerGymId();
    if(_gid)await fetch('/api/gym-partner/toggle-active',{method:'PATCH',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({gymId:_gid,isActive:isOpen})}).catch(()=>{});
    // Fallback to old API
    if(_gid)await fetch('/api/owner/toggle/'+_gid,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({isOpen})}).catch(()=>{});
  }catch(e){}
};

// #89: Hours override handler
window.sgOwnerHoursOverride=async function(overrideStatus){
  var el=document.getElementById('sg-hours-result');
  if(el) el.innerHTML='<p style="color:rgba(255,255,255,.4);font-size:12px;margin-top:8px">Updating...</p>';
  try{
    var _gid=await window._sgResolvePartnerGymId();
    if(!_gid){if(el) el.innerHTML='<p style="color:#f87171;font-size:12px;margin-top:8px">Claim your gym first</p>';return;}
    var r=await fetch('/api/gym-partner/hours-override',{method:'PATCH',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({gymId:_gid,overrideStatus:overrideStatus})});
    var d=await r.json();
    if(el) el.innerHTML='<p style="color:#4ade80;font-size:12px;margin-top:8px">'+(d.message||'Updated')+'</p>';
  }catch(e){if(el) el.innerHTML='<p style="color:#f87171;font-size:12px;margin-top:8px">Failed to update</p>';}
};

// #86: Tag toggle handler (24/7, self-serve)
window.sgOwnerTag=async function(tag,val){
  var _gid=await window._sgResolvePartnerGymId();
  if(!_gid)return;
  var body={gymId:_gid}; body[tag.replace('is_','is')]=val; body['is24h']=undefined; body['isSelfServe']=undefined;
  if(tag==='is_24h') body={gymId:_gid,is24h:val};
  if(tag==='is_self_serve') body={gymId:_gid,isSelfServe:val};
  try{
    await fetch('/api/gym-partner/claim/preferences',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(body)});
  }catch(e){}
};

// Owner price update handler
window.sgOwnerUpdatePrice=async function(){
  var input=document.getElementById('sg-owner-price-day');
  var result=document.getElementById('sg-price-result');
  if(!input)return;
  var price=parseFloat(input.value);
  if(isNaN(price)||price<3||price>25){
    if(result)result.innerHTML='<p style="color:#f87171;font-size:12px">Day pass price must be between \u00A33 and \u00A325</p>';
    return;
  }
  var pence=Math.round(price*100);
  if(result)result.innerHTML='<p style="color:rgba(255,255,255,.5);font-size:12px">Updating...</p>';
  try{
    var r=await fetch('/api/owner/price-limits/0',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({dayPassPence:pence})}).then(function(r){return r.json();});
    if(r.success){
      if(result)result.innerHTML='<p style="color:#4ade80;font-size:12px">\u2705 Price updated to \u00A3'+r.price+'</p>';
    }else{
      if(result)result.innerHTML='<p style="color:#f87171;font-size:12px">'+(r.error||'Failed to update')+'</p>';
    }
  }catch(e){
    if(result)result.innerHTML='<p style="color:#f87171;font-size:12px">Network error</p>';
  }
};
window.sgOwnerUpdateAllPrices=async function(){
  var result=document.getElementById('sg-price-result');
  var prices={};
  var valid=true;
  [{id:'day',min:3,max:25},{id:'3day',min:8,max:50},{id:'week',min:15,max:80},{id:'month',min:30,max:200}].forEach(function(p){
    var el=document.getElementById('sg-owner-price-'+p.id);
    if(!el)return;
    var v=parseFloat(el.value);
    if(isNaN(v)||v<p.min||v>p.max){valid=false;return;}
    prices[p.id+'PassPence']=Math.round(v*100);
  });
  if(!valid){if(result)result.innerHTML='<p style="color:#f87171;font-size:12px">Please check all prices are within valid ranges</p>';return;}
  if(result)result.innerHTML='<p style="color:rgba(255,255,255,.5);font-size:12px">Updating all prices...</p>';
  try{
    var r=await fetch('/api/owner/price-limits/0',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(prices)}).then(function(r){return r.json();});
    if(r.success){
      if(result)result.innerHTML='<p style="color:#4ade80;font-size:12px">\u2705 All prices updated successfully!</p>';
    }else{
      if(result)result.innerHTML='<p style="color:#f87171;font-size:12px">'+(r.error||'Failed to update')+'</p>';
    }
  }catch(e){
    if(result)result.innerHTML='<p style="color:#f87171;font-size:12px">Network error</p>';
  }
};

// Access Control connection UI handler
window.sgShowAccessConnect=function(system){
  var form=document.getElementById('sg-access-form');
  if(!form) return;
  form.style.display='block';
  var configs={
    kisi:{name:'QR Access',color:'#3b82f6',fields:[
      {id:'kisiApiKey',label:'API Key',placeholder:'Your access system API key',type:'password'},
      {id:'kisiPlaceId',label:'Place ID (optional)',placeholder:'Auto-detected if blank',type:'text'}
    ],endpoint:'/api/access/owner/connect-kisi',bodyFn:function(){return{gymId:0,kisiApiKey:document.getElementById('kisiApiKey').value,placeId:document.getElementById('kisiPlaceId').value||undefined}}},
    salto:{name:'Salto KS',color:'#4ade80',fields:[
      {id:'seamSystemId',label:'ACS System ID',placeholder:'acs_system_...',type:'text'}
    ],endpoint:'/api/access/owner/connect-seam',bodyFn:function(){return{gymId:0,seamAcsSystemId:document.getElementById('seamSystemId').value,accessType:'code'}}},
    brivo:{name:'Brivo',color:'#a855f7',fields:[
      {id:'seamSystemId',label:'ACS System ID',placeholder:'acs_system_...',type:'text'}
    ],endpoint:'/api/access/owner/connect-seam',bodyFn:function(){return{gymId:0,seamAcsSystemId:document.getElementById('seamSystemId').value,accessType:'mobile_key'}}},
    gymmaster:{name:'GymMaster',color:'#FF6D00',fields:[
      {id:'seamSystemId',label:'ACS System ID',placeholder:'acs_system_...',type:'text'}
    ],endpoint:'/api/access/owner/connect-seam',bodyFn:function(){return{gymId:0,seamAcsSystemId:document.getElementById('seamSystemId').value,accessType:'code'}}}
  };
  var c=configs[system];
  if(!c) return;
  form.innerHTML='<div style="background:rgba(255,255,255,.03);border:1px solid '+c.color+'33;border-radius:12px;padding:16px">'+
    '<p style="color:'+c.color+';font-weight:700;font-size:14px;margin-bottom:12px">Connect '+c.name+'</p>'+
    c.fields.map(function(f){return '<div style="margin-bottom:10px"><label style="color:rgba(255,255,255,.5);font-size:11px;display:block;margin-bottom:4px">'+f.label+'</label><input id="'+f.id+'" type="'+f.type+'" placeholder="'+f.placeholder+'" style="width:100%;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);border-radius:8px;padding:10px 12px;color:#fff;font-size:13px;outline:none;box-sizing:border-box"></div>'}).join('')+
    '<div style="display:flex;gap:8px;margin-top:12px">'+
    '<button onclick="sgConnectAccess(\''+system+'\')" style="flex:1;background:'+c.color+';color:#fff;border:none;padding:12px;border-radius:10px;font-weight:700;font-size:13px;cursor:pointer">Connect '+c.name+' →</button>'+
    '<button onclick="document.getElementById(\'sg-access-form\').style.display=\'none\'" style="background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08);color:rgba(255,255,255,.5);padding:12px 16px;border-radius:10px;font-size:13px;cursor:pointer">Cancel</button>'+
    '</div>'+
    (system==='kisi'?'<p style="color:rgba(255,255,255,.3);font-size:10px;margin-top:8px">Find your API key in your access provider dashboard → Settings → API</p>':'<p style="color:rgba(255,255,255,.3);font-size:10px;margin-top:8px">Get your System ID from your access control dashboard</p>')+
    '</div>';
  window._sgAccessConfig=c;
};

window.sgConnectAccess=async function(system){
  var c=window._sgAccessConfig;
  if(!c) return;
  var result=document.getElementById('sg-access-result');
  if(result) result.innerHTML='<p style="color:rgba(255,255,255,.5);font-size:12px">Connecting '+c.name+'...</p>';
  try{
    var body=c.bodyFn();
    var _gid=await window._sgResolvePartnerGymId();
    if(!_gid){if(result) result.innerHTML='<p style="color:#f87171;font-size:12px">Claim your gym first, then connect access</p>';return;}
    body.gymId=_gid;
    var r=await fetch(c.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(body)});
    var d=await r.json();
    if(d.connected){
      if(result) result.innerHTML='<p style="color:#4ade80;font-size:12px">✅ '+c.name+' connected! '+(d.message||'')+'</p>';
      document.getElementById('sg-access-form').style.display='none';
      var status=document.getElementById('sg-access-status');
      if(status) status.innerHTML='<div style="display:flex;align-items:center;gap:8px"><span style="font-size:16px">🔐</span><div><p style="color:#4ade80;font-size:13px;font-weight:600">'+c.name+' Connected ✓</p><p style="color:rgba(255,255,255,.3);font-size:11px">Customers get auto access on booking</p></div></div>';
    }else{
      if(result) result.innerHTML='<p style="color:#f87171;font-size:12px">❌ '+(d.error||'Connection failed')+'</p>';
    }
  }catch(e){
    if(result) result.innerHTML='<p style="color:#f87171;font-size:12px">Network error — check connection</p>';
  }
};

// ═══════════════════════════════════════════════════════════════════
//  UNIVERSAL SCANGYM PROFILE — "One signup. Any gym. No membership."
// ═══════════════════════════════════════════════════════════════════

// ── ScanGym ID Card (QR-based universal pass) ──
function ScanGymIDCard(u){
  if(!u)return'';
  const name=u.name||u.phone||'Member';
  const initial=(name).charAt(0).toUpperCase();
  const since=u.member_since?new Date(u.member_since).toLocaleDateString('en-GB',{month:'short',year:'numeric'}):'2026';
  const verified=u.profile_complete;
  const qrData=encodeURIComponent('https://scangym.com/member/'+u.id);
  const qrUrl='https://api.qrserver.com/v1/create-qr-code/?size=120x120&bgcolor=0d0d1a&color=FF6D00&data='+qrData;
  // Enhanced stats (Fix #8E)
  const totalSessions=u.stats?.totalSessions||0;
  const totalGyms=u.stats?.totalGyms||0;
  const streak=u.stats?.streak||0;
  // Tier system
  const tier=totalSessions>=100?{name:'Elite',icon:'👑',color:'#a855f7',bg:'rgba(168,85,247,.15)'}:
             totalSessions>=50?{name:'Gold',icon:'🥇',color:'#eab308',bg:'rgba(234,179,8,.15)'}:
             totalSessions>=10?{name:'Silver',icon:'🥈',color:'#94a3b8',bg:'rgba(148,163,184,.15)'}:
             {name:'Basic',icon:'🏋️',color:'#FF6D00',bg:'rgba(255,109,0,.15)'};
  return`<div style="background:linear-gradient(135deg,rgba(255,109,0,.12),rgba(255,109,0,.04));border:1px solid rgba(255,109,0,.2);border-radius:20px;padding:20px;margin-bottom:20px;position:relative;overflow:hidden">
    <div style="position:absolute;top:-30px;right:-30px;width:120px;height:120px;background:radial-gradient(circle,rgba(255,109,0,.08),transparent);border-radius:50%"></div>
    <!-- Tier Badge -->
    <div style="position:absolute;top:12px;right:12px;background:${tier.bg};border:1px solid ${tier.color}33;padding:3px 10px;border-radius:8px;display:flex;align-items:center;gap:4px">
      <span style="font-size:10px">${tier.icon}</span>
      <span style="font-size:10px;font-weight:800;color:${tier.color};text-transform:uppercase;letter-spacing:1px">${tier.name}</span>
    </div>
    <div style="display:flex;align-items:center;gap:16px;margin-bottom:12px">
      <div style="flex:1">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
          <span style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:2px;color:rgba(255,109,0,.7)">ScanGym ID</span>
          ${verified?'<span style="background:rgba(74,222,128,.15);color:#4ade80;font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px;display:inline-flex;align-items:center;gap:3px">✓ Verified</span>':'<span style="background:rgba(251,191,36,.1);color:#fbbf24;font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px">Complete profile</span>'}
        </div>
        <div style="color:#fff;font-size:18px;font-weight:800;margin-bottom:2px">${name}</div>
        <div style="color:rgba(255,255,255,.4);font-size:12px">Member since ${since}</div>
      </div>
      <div onclick="_sgShowFullScreenQR('${name}','${since}','${tier.name}','${tier.icon}','${tier.color}','${qrUrl.replace(/'/g,"\\'")}','${u.id||''}')" style="flex-shrink:0;width:80px;height:80px;background:rgba(0,0,0,.3);border-radius:14px;display:flex;align-items:center;justify-content:center;border:1px solid rgba(255,109,0,.15);cursor:pointer;position:relative">
        <img src="${qrUrl}" width="64" height="64" style="border-radius:8px" alt="QR">
        <div style="position:absolute;bottom:-2px;right:-2px;width:20px;height:20px;background:#FF6D00;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;box-shadow:0 2px 6px rgba(0,0,0,.4)">⛶</div>
      </div>
    </div>
    <!-- Stats Row (Fix #8E) -->
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:8px">
      <div style="text-align:center;background:rgba(255,255,255,.04);border-radius:10px;padding:8px 4px">
        <div style="color:#FF6D00;font-size:20px;font-weight:900">${totalSessions}</div>
        <div style="color:rgba(255,255,255,.3);font-size:9px;font-weight:600;text-transform:uppercase">Sessions</div>
      </div>
      <div style="text-align:center;background:rgba(255,255,255,.04);border-radius:10px;padding:8px 4px">
        <div style="color:#22c55e;font-size:20px;font-weight:900">${totalGyms}</div>
        <div style="color:rgba(255,255,255,.3);font-size:9px;font-weight:600;text-transform:uppercase">Gyms</div>
      </div>
      <div style="text-align:center;background:rgba(255,255,255,.04);border-radius:10px;padding:8px 4px">
        <div style="color:#3b82f6;font-size:20px;font-weight:900">${streak}🔥</div>
        <div style="color:rgba(255,255,255,.3);font-size:9px;font-weight:600;text-transform:uppercase">Streak</div>
      </div>
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between">
      <div style="display:flex;align-items:center;gap:6px">
        <span style="width:6px;height:6px;background:#4ade80;border-radius:50%;display:inline-block"></span>
        <span style="color:rgba(255,255,255,.5);font-size:11px;font-weight:600">Book any gym — no membership needed</span>
      </div>
      <button onclick="event.stopPropagation();_shareIDCard()" style="background:none;border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.4);font-size:10px;padding:4px 10px;border-radius:8px;cursor:pointer;font-weight:600">📤 Share</button>
    </div>
  </div>`;
}
// ═══ FULL-SCREEN QR CODE (TikTok-style immersive overlay) ═══
window._sgShowFullScreenQR=function(name,since,tierName,tierIcon,tierColor,qrUrl,memberId){
  // Generate larger QR code for full-screen display
  var qrData=encodeURIComponent('https://scangym.com/member/'+memberId);
  var qrUrlLarge='https://api.qrserver.com/v1/create-qr-code/?size=300x300&bgcolor=0d0d1a&color=FF6D00&data='+qrData;
  var overlay=document.createElement('div');
  overlay.id='sg-qr-fullscreen';
  overlay.style.cssText='position:fixed;inset:0;z-index:99999;background:linear-gradient(180deg,#0a0c14 0%,#111525 30%,#0d0f1a 100%);display:flex;flex-direction:column;align-items:center;justify-content:center;animation:sgQRFadeIn .3s ease;-webkit-tap-highlight-color:transparent';
  overlay.innerHTML=
    '<style>'+
    '@keyframes sgQRFadeIn{from{opacity:0;transform:scale(.95)}to{opacity:1;transform:scale(1)}}'+
    '@keyframes sgQRPulse{0%,100%{box-shadow:0 0 0 0 rgba(255,109,0,.3),0 20px 60px rgba(255,109,0,.15)}50%{box-shadow:0 0 0 20px rgba(255,109,0,0),0 20px 60px rgba(255,109,0,.25)}}'+
    '@keyframes sgQRGlow{0%,100%{opacity:.3}50%{opacity:.6}}'+
    '</style>'+
    // Close button (top-right)
    '<div onclick="document.getElementById(\'sg-qr-fullscreen\').remove()" style="position:absolute;top:max(16px,env(safe-area-inset-top,16px));right:16px;width:40px;height:40px;background:rgba(255,255,255,.08);backdrop-filter:blur(12px);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:18px;cursor:pointer;z-index:5;color:rgba(255,255,255,.6)">✕</div>'+
    // ScanGym branding top
    '<div style="position:absolute;top:max(20px,env(safe-area-inset-top,20px));left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px">'+
      '<div style="width:32px;height:32px;background:#FF6D00;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:900;color:#fff">S</div>'+
      '<span style="color:#fff;font-size:16px;font-weight:800;letter-spacing:-.3px">ScanGym</span>'+
    '</div>'+
    // Ambient glow behind QR
    '<div style="position:absolute;width:350px;height:350px;background:radial-gradient(circle,rgba(255,109,0,.12),transparent 70%);border-radius:50%;animation:sgQRGlow 3s ease-in-out infinite;pointer-events:none"></div>'+
    // QR code container
    '<div style="position:relative;background:rgba(255,255,255,.03);border:2px solid rgba(255,109,0,.25);border-radius:32px;padding:32px;animation:sgQRPulse 2.5s ease-in-out infinite;backdrop-filter:blur(20px)">'+
      '<img src="'+qrUrlLarge+'" style="width:min(280px,65vw);height:min(280px,65vw);border-radius:16px;display:block" alt="ScanGym QR Code">'+
    '</div>'+
    // Member info below QR
    '<div style="margin-top:28px;text-align:center">'+
      '<h2 style="color:#fff;font-size:24px;font-weight:900;margin:0 0 6px;letter-spacing:-.3px">'+name+'</h2>'+
      '<div style="display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:4px">'+
        '<span style="background:rgba(255,109,0,.12);border:1px solid rgba(255,109,0,.2);padding:4px 12px;border-radius:20px;font-size:12px;font-weight:700;color:'+tierColor+';display:flex;align-items:center;gap:4px">'+tierIcon+' '+tierName+'</span>'+
      '</div>'+
      '<p style="color:rgba(255,255,255,.4);font-size:13px;margin:6px 0 0">Member since '+since+'</p>'+
    '</div>'+
    // Instructions at bottom
    '<div style="position:absolute;bottom:max(40px,env(safe-area-inset-bottom,40px));text-align:center;padding:0 24px">'+
      '<p style="color:rgba(255,255,255,.35);font-size:13px;font-weight:600;margin:0 0 6px">📱 Show this QR at the gym entrance</p>'+
      '<p style="color:rgba(255,255,255,.2);font-size:11px;margin:0">Tap anywhere to close</p>'+
    '</div>';
  // Close on background tap
  overlay.addEventListener('click',function(e){
    if(e.target===overlay)overlay.remove();
  });
  // Close on swipe down
  var startY=0;
  overlay.addEventListener('touchstart',function(e){startY=e.touches[0].clientY;},{passive:true});
  overlay.addEventListener('touchend',function(e){
    if(e.changedTouches[0].clientY-startY>100)overlay.remove();
  },{passive:true});
  document.body.appendChild(overlay);
  // Increase screen brightness hint (if supported)
  try{if(screen.orientation)screen.keepAwake=true;}catch(e){}
};

// Share ID card handler (Fix #8E)
window._shareIDCard=function(){
  if(navigator.share){
    navigator.share({title:'My ScanGym ID',text:'Check out my ScanGym gym pass! Book any gym. No membership needed.',url:'https://scangym.com'}).catch(()=>{});
  }else{
    navigator.clipboard.writeText('https://scangym.com').then(()=>sgToast('Link copied!','success',2000)).catch(()=>{});
  }
};

