// ═══════════════════════════════════════════════════════════════
//  Push Notification Registration & Scheduling (Fix #7C)
// ═══════════════════════════════════════════════════════════════
window._sgPushEnabled=false;
window.sgEnablePushNotifications=async function(){
  try{
    if(!('Notification' in window)||!('serviceWorker' in navigator)){
      sgToast('Push notifications not supported on this browser','info',3000);
      return false;
    }
    const permission=await Notification.requestPermission();
    if(permission!=='granted'){
      sgToast('Notifications blocked — enable in browser settings','info',3000);
      return false;
    }
    const reg=await navigator.serviceWorker.ready;
    let sub=await reg.pushManager.getSubscription();
    if(!sub){
      // Generate VAPID key or use server's public key
      sub=await reg.pushManager.subscribe({
        userVisibleOnly:true,
        applicationServerKey:'BEl62iUYgUivxIkv69yViEuiBIa-Ib9-SkvMeAtA3LFgDzkOs-qy3PJbi6GR3JMrJL6s7xP5popTxCjpGZdqHgA'
      }).catch(()=>null);
    }
    if(sub){
      // Send subscription to server
      await fetch('/api/notifications/subscribe',{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        credentials:'include',
        body:JSON.stringify({subscription:sub.toJSON()})
      }).catch(()=>{});
      window._sgPushEnabled=true;
      localStorage.setItem('sg_push_enabled','1');
      sgToast('🔔 Notifications enabled! You\'ll get session reminders.','success',3000);
      return true;
    }
    return false;
  }catch(e){
    console.error('[Push] Registration error:',e);
    return false;
  }
};

// Schedule local notification for booking (uses setTimeout fallback when push server unavailable)
window.sgScheduleSessionNotification=function(booking){
  if(!booking||!window._sgPushEnabled)return;
  const sessionTime=new Date(booking.date+' '+booking.time).getTime();
  const now=Date.now();
  const oneHourBefore=sessionTime-3600000;
  // T-1hr reminder
  if(oneHourBefore>now){
    setTimeout(function(){
      if('Notification' in window&&Notification.permission==='granted'){
        new Notification('ScanGym Session in 1 hour! 🏋️',{
          body:'Your session at '+(booking.gymName||'the gym')+' starts soon. Don\'t forget your phone for QR entry!',
          icon:'/icons/icon-192.png',
          tag:'session-reminder'
        });
      }
    },oneHourBefore-now);
  }
  // At session time
  if(sessionTime>now){
    setTimeout(function(){
      if('Notification' in window&&Notification.permission==='granted'){
        new Notification('Time to go! 💪',{
          body:'Show your QR code at '+(booking.gymName||'the gym')+' entrance. Have a great workout!',
          icon:'/icons/icon-192.png',
          tag:'session-active'
        });
      }
    },sessionTime-now);
  }
};

// Auto-enable push on login if previously enabled
if(localStorage.getItem('sg_push_enabled')==='1'&&state.user){
  sgEnablePushNotifications().catch(()=>{});
}

/* ═══ Sticky Continue Banner (permanent layout element) ═══
 * Part of the bottom layout on Reels + Book tabs — like the tab bar itself.
 * Content areas resize above it; nothing is covered.
 * Reels tab: "Continue · £4.49 →" navigates to Book tab.
 * Book tab: "Continue · £4.49 →" navigates to checkout for visible gym.
 * Profile tab: banner hidden, content resizes back to tab bar only. */
(function(){
  var banner=document.createElement('div');
  banner.id='sg-continue-banner';
  banner.className='sg-cb-hidden';
  banner.innerHTML='<span class="sg-cb-text">Find gyms near me</span><span class="sg-cb-price"></span><span class="sg-cb-arrow">\ud83d\udccd</span>';

  banner.addEventListener('click',function(){
    var activeLabel=document.querySelector('.sg-tab-item.active .sg-tab-label');
    var currentTab=activeLabel?activeLabel.textContent.trim().toLowerCase():'';
    if(currentTab==='book'){
      // On Book tab: go to checkout for the currently visible gym card.
      // FIX: Use scroll position to find the card actually in view, not just
      // the first non-offscreen card (IntersectionObserver rootMargin:600px
      // marks multiple cards as visible, querySelector always returned card 0).
      var carousel=document.getElementById('bm-carousel');
      var card=null;
      if(carousel){
        var cards=carousel.querySelectorAll('.tt-card');
        var scrollTop=carousel.scrollTop;
        var viewH=carousel.clientHeight;
        var bestCard=null;var bestOverlap=0;
        cards.forEach(function(c){
          var top=c.offsetTop;var h=c.offsetHeight;
          var overlapStart=Math.max(top,scrollTop);
          var overlapEnd=Math.min(top+h,scrollTop+viewH);
          var overlap=Math.max(0,overlapEnd-overlapStart);
          if(overlap>bestOverlap){bestOverlap=overlap;bestCard=c;}
        });
        card=bestCard;
      }
      if(!card) card=document.querySelector('.tt-card:not(.tt-offscreen)');
      var gid=card?(card.getAttribute('data-gym-id')||card.getAttribute('data-id')):null;
      if(gid&&typeof showBookingCheckout==='function'){showBookingCheckout(gid);}
    }else{
      // On Reels: check auth first, then navigate to Book tab
      if(state.user){
        // Already logged in — go straight to Book tab
        if(typeof switchTab==='function')switchTab('book');
      }else{
        // Not logged in — show auth sheet, then navigate to Book on success
        window._pendingReelsAction='switch-to-book';
        if(typeof window._sgShowAuthSheet==='function'){
          window._sgShowAuthSheet('reels');
        }else if(typeof switchTab==='function'){
          switchTab('book');
        }
      }
    }
  });
  document.body.appendChild(banner);

  var _cbVisible=false;

  /* UX fix: banner price must match the gym card actually in view (cards carry
   * data-price, which can be gym-specific / PPP) — not the generic default,
   * which caused e.g. "$5.49/day" on the card vs "£4.49" on Continue. */
  function _visibleCardPrice(){
    var carousel=document.getElementById('bm-carousel');
    if(!carousel)return null;
    var cards=carousel.querySelectorAll('.tt-card[data-price]');
    if(!cards.length)return null;
    var scrollTop=carousel.scrollTop,viewH=carousel.clientHeight;
    var best=null,bestOverlap=0;
    cards.forEach(function(c){
      var top=c.offsetTop,h=c.offsetHeight;
      var overlap=Math.max(0,Math.min(top+h,scrollTop+viewH)-Math.max(top,scrollTop));
      if(overlap>bestOverlap){bestOverlap=overlap;best=c;}
    });
    var p=best&&best.getAttribute('data-price');
    return(p&&p!=='undefined'&&p!=='null')?p:null;
  }
  function _updatePrice(){
    var priceEl=banner.querySelector('.sg-cb-price');
    if(!priceEl)return;
    /* FIX #2: Only show price on Book tab, NOT on Reels */
    var activeLabel=document.querySelector('.sg-tab-item.active .sg-tab-label');
    var currentTab=activeLabel?activeLabel.textContent.trim().toLowerCase():'';
    /* R4-#2 FIX: banner label must match what the tap actually does.
       On Book tab the tap opens checkout for the visible gym, so label it
       "Book this gym" (was the misleading "Find gyms near me" everywhere,
       which read as search, not booking). Reels tap jumps to Book/search. */
    var textEl=banner.querySelector('.sg-cb-text');
    var arrowEl=banner.querySelector('.sg-cb-arrow');
    if(currentTab==='book'){
      if(textEl)textEl.textContent='Book this gym';
      if(arrowEl)arrowEl.textContent='\u2192';
    }else{
      if(textEl)textEl.textContent='Find gyms near me';
      if(arrowEl)arrowEl.textContent='\ud83d\udccd';
    }
    if(currentTab==='book'){
      var gymP=_visibleCardPrice();
      if(gymP){priceEl.textContent='\u00b7 '+gymP;return;}
      var dp=(typeof sgPrice==='function')?sgPrice('day'):null;
      priceEl.textContent=dp&&dp.display?('\u00b7 '+dp.display):'';
    }else{
      priceEl.textContent='';
    }
  }
  /* Keep price in sync while swiping through gym cards */
  document.addEventListener('scroll',function(e){
    if(!e.target||e.target.id!=='bm-carousel')return;
    if(window._sgCbPriceT)clearTimeout(window._sgCbPriceT);
    window._sgCbPriceT=setTimeout(_updatePrice,150);
  },true);
  /* Cards load async after the banner appears — refresh until they exist */
  setInterval(function(){if(_cbVisible)_updatePrice();},2000);

  function _showBanner(){
    _updatePrice();
    if(_cbVisible)return;
    _cbVisible=true;
    banner.classList.remove('sg-cb-hidden');
    // R7 FIX: Toggle on <body> — survives render() DOM rebuilds
    // (render() replaces #app.innerHTML, destroying per-element classes)
    document.body.classList.add('sg-cb-active');
  }

  function _hideBanner(){
    if(!_cbVisible)return;
    _cbVisible=false;
    banner.classList.add('sg-cb-hidden');
    document.body.classList.remove('sg-cb-active');
  }

  window._sgShowContinueBanner=function(){_showBanner();};
  window._sgHideContinueBanner=function(){_hideBanner();};

  // Show on Reels + Book, hide on Profile
  // R7: body class approach means order doesn't matter — class survives render()
  var _origSwitchTab=window.switchTab;
  if(typeof _origSwitchTab==='function'){
    window.switchTab=function(tab){
      if(tab==='reels'||tab==='book'){
        _cbVisible=false;
        _showBanner();
      }else{
        _hideBanner();
      }
      _origSwitchTab.apply(this,arguments);
    };
  }

  // Show on initial load (default tab is Reels)
  setTimeout(function(){
    var activeLabel=document.querySelector('.sg-tab-item.active .sg-tab-label');
    var tab=activeLabel?activeLabel.textContent.trim().toLowerCase():'';
    if(tab==='reels'||tab==='book'){
      _showBanner();
    }
  },500);
})();

