// ─── Pinterest-style: Save gym to board ───
window._sgSaveGym=function(gymId,gymName,btnEl){
  fetch('/api/referrals/gyms/save',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({gymId:gymId,gymName:gymName})}).then(function(r){return r.json()}).then(function(d){
    if(d.error&&d.error.includes('Sign in')){
      // Not signed in — trigger auth then retry
      window._sheetMode='save_gym';window._pendingSaveGym={gymId:gymId,gymName:gymName};
      if(typeof _sgShowAuthSheet==='function')_sgShowAuthSheet();
      return;
    }
    var iconEl=document.getElementById('tt-save-btn-'+gymId);
    var labelEl=document.getElementById('tt-save-label-'+gymId);
    if(d.saved){
      if(iconEl)iconEl.textContent='✅';
      if(labelEl){labelEl.textContent='Saved';labelEl.style.color='#4ade80';}
      sgToast('💪 Saving branded image…','success',2000);
      // TikTok-style: watermark image with ScanGym branding and download
      window._sgDownloadBrandedImage(gymId,gymName);
    }else{
      if(iconEl)iconEl.textContent='🔖';
      if(labelEl){labelEl.textContent='Save';labelEl.style.color='';}
      sgToast('Removed from saved','info',2000);
    }
  }).catch(function(){sgToast('Could not save gym','error',2000);});
};

// ── TikTok-style branded image download ──
// Draws the gym photo on a canvas, adds ScanGym orange watermark, and triggers download
window._sgDownloadBrandedImage=function(gymId,gymName){
  // Find the current visible photo for this gym
  var card=document.querySelector('.tt-card[data-gym-id="'+gymId+'"]')||document.querySelector('.tt-card[data-id="'+gymId+'"]');
  var photoUrl='';
  if(card){
    // Check photo carousel first (active slide)
    var carousel=card.querySelector('.tt-photo-carousel');
    if(carousel){
      var slides=carousel.querySelectorAll('.tt-photo-slide');
      var scrollL=carousel.scrollLeft;var w=carousel.clientWidth;
      var idx=Math.round(scrollL/w);
      var slide=slides[Math.min(idx,slides.length-1)]||slides[0];
      if(slide){
        var bg=slide.style.backgroundImage||'';
        photoUrl=bg.replace(/^url\(['"]?/,'').replace(/['"]?\)$/,'')||slide.getAttribute('data-bg')||'';
        // Check if it's a video slide
        var vid=slide.querySelector('video');
        if(vid){photoUrl='';} // Can't watermark video frames easily
      }
    }
    if(!photoUrl){
      var photoDiv=card.querySelector('.tt-photo');
      if(photoDiv){
        var bg=photoDiv.style.backgroundImage||'';
        photoUrl=bg.replace(/^url\(['"]?/,'').replace(/['"]?\)$/,'')||photoDiv.getAttribute('data-bg')||'';
      }
    }
  }
  if(!photoUrl){sgToast('📷 No image to save','info',2000);return;}

  // Load image, draw on canvas, add watermark
  var img=new Image();
  img.crossOrigin='anonymous';
  img.onload=function(){
    var canvas=document.createElement('canvas');
    var W=img.naturalWidth||img.width;
    var H=img.naturalHeight||img.height;
    // Cap at 1080px width for mobile-friendly download
    if(W>1080){var ratio=1080/W;W=1080;H=Math.round(H*ratio);}
    canvas.width=W;canvas.height=H;
    var ctx=canvas.getContext('2d');
    ctx.drawImage(img,0,0,W,H);

    // ── 🟠 Orange circle branding (same as reels/book tab top-left identity) ──
    var scale=W/1080;
    var brandColor='#FF6D00';
    // Orange circle — top-left, matching the in-app brand circle
    var circR=Math.round(20*scale);
    var circX=Math.round(28*scale);
    var circY=Math.round(28*scale);
    ctx.globalAlpha=0.85;
    ctx.fillStyle=brandColor;
    ctx.beginPath();ctx.arc(circX,circY,circR,0,Math.PI*2);ctx.fill();
    // Glow shadow
    ctx.shadowColor='rgba(255,109,0,0.5)';ctx.shadowBlur=Math.round(10*scale);
    ctx.beginPath();ctx.arc(circX,circY,circR,0,Math.PI*2);ctx.fill();
    ctx.shadowColor='transparent';ctx.shadowBlur=0;
    ctx.globalAlpha=1.0;

    // Download
    try{
      canvas.toBlob(function(blob){
        if(!blob){sgToast('Could not create image','error',2000);return;}
        var url=URL.createObjectURL(blob);
        var a=document.createElement('a');
        a.href=url;a.download='scangym-'+(gymName||'gym').replace(/[^a-z0-9]/gi,'-').toLowerCase()+'.jpg';
        document.body.appendChild(a);a.click();
        setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url);},500);
        sgToast('📸 Branded image saved!','success',2500);
      },'image/jpeg',0.92);
    }catch(e){
      sgToast('Could not download image','error',2000);
      console.warn('[BrandedImage] Download failed:',e);
    }
  };
  img.onerror=function(){
    // CORS blocked — try without crossOrigin as fallback toast
    sgToast('📷 Image saved to board (download not available for this photo)','info',3000);
  };
  img.src=photoUrl;
};

// ─── Amazon Tracking ID style: Copy channel-specific affiliate link ───
window._sgCopyChannelLink=function(handle,channel){
  var link='https://scangym.com/r/'+encodeURIComponent(handle)+'?src='+encodeURIComponent(channel);
  navigator.clipboard.writeText(link).then(function(){
    var channelNames={tiktok:'TikTok',instagram:'Instagram',youtube:'YouTube',twitter:'Twitter',facebook:'Facebook',snapchat:'Snapchat',pinterest:'Pinterest',linkedin:'LinkedIn',whatsapp:'WhatsApp',blog:'Blog',email:'Email'};
    sgToast('🔗 '+(channelNames[channel]||channel)+' link copied!','success',2500);
    // Track link generation
    fetch('/api/referrals/generate-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creatorHandle:handle,source:channel})}).catch(function(){});
  }).catch(function(){sgToast('Could not copy link','error',2000);});
};

// ─── Two share modes (user request): plain Share + deep Affiliate Share ───
// _sgShareGymLink(gymId,gymName)        -> plain link, no tracking, no login needed
// _sgShareGymLink(gymId,gymName,true)   -> deep affiliate link with ?ref= (login required)
window._sgShareAffiliateLink=function(gymId,gymName){window._sgShareGymLink(gymId,gymName,true);};
window._sgShareGymLink=function(gymId,gymName,affiliate){
  // Affiliate share needs an account (the ?ref= handle comes from the user)
  if(affiliate&&!state.user){
    window._pendingShareGym={gymId:gymId,gymName:gymName,affiliate:true};
    window._pendingReelsAction='share-gym';
    if(typeof window._sgShowAuthSheet==='function'){
      window._sgShowAuthSheet('reels');
    }
    return;
  }

  var creator=null;
  if(affiliate){
    // Get creator handle from localStorage (if user is a creator)
    try{var c=JSON.parse(localStorage.getItem('sg_creator')||'null');if(c&&c.handle)creator=c.handle;}catch(e){}
    // Every logged-in user has an affiliate referral_handle (auth.js) — fall back
    // so Affiliate Share always produces a deep link. Wallet credit for
    // referral_handle conversions is handled server-side (resolveReferralUserId).
    if(!creator&&state.user&&state.user.referralHandle)creator=state.user.referralHandle;
    if(!creator){sgToast('Could not find your affiliate handle — try re-logging in','error',3000);return;}
  }

  var baseUrl='https://scangym.com';
  var link;
  if(creator){
    // Deep affiliate link with the user's handle (30-day attribution)
    link=baseUrl+'/gym/'+gymId+'?ref='+encodeURIComponent(creator);
  }else{
    // Plain share — clean link, no tracking params
    link=baseUrl+'/gym/'+gymId;
  }

  var shareText='Check out '+gymName+' on ScanGym! 🏋️ No membership needed, just scan & train:';

  // Use native share if available, otherwise copy
  if(navigator.share){
    navigator.share({title:'ScanGym — '+gymName,text:shareText,url:link}).then(function(){
      // Track share event for creators
      if(creator){fetch('/api/referrals/track-download',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creatorHandle:creator,assetType:'gym_share',assetId:gymId})}).catch(function(){});}
    }).catch(function(){});
  }else{
    navigator.clipboard.writeText(shareText+' '+link).then(function(){
      sgToast(creator?'💰 Affiliate link copied — you earn on bookings!':'🔗 Link copied!','success',2500);
      if(creator){fetch('/api/referrals/track-download',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creatorHandle:creator,assetType:'gym_share',assetId:gymId})}).catch(function(){});}
    }).catch(function(){sgToast('Could not copy link','error',2000);});
  }

  // Log link generation server-side if creator
  if(creator){
    fetch('/api/referrals/generate-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creatorHandle:creator,gymId:gymId,gymName:gymName})}).catch(function(){});
  }
};

// ─── Auto-trigger signup bounty when user registers via referral link ───
(function(){
  // Hook into auth success to credit bounty to referring creator
  var _origAfterAuth=window._afterAuthSuccessOriginal||null;
  // We watch for the sg_onboarded flag to trigger bounty
  var _bountyInterval=setInterval(function(){
    try{
      var onboarded=localStorage.getItem('sg_onboarded');
      var bountySent=localStorage.getItem('sg_bounty_sent');
      if(onboarded&&!bountySent){
        var ref=JSON.parse(localStorage.getItem('sg_referral')||'null');
        if(ref&&ref.handle&&ref.expiry>Date.now()){
          var userId=localStorage.getItem('sg_uid')||('anon_'+Date.now().toString(36));
          fetch('/api/referrals/bounty',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creatorHandle:ref.handle,userId:userId,bountyType:'signup'})}).catch(function(){});
          localStorage.setItem('sg_bounty_sent','1');
          clearInterval(_bountyInterval);
        }
      }
    }catch(e){}
  },3000);
  // Stop checking after 60 seconds
  setTimeout(function(){clearInterval(_bountyInterval);},60000);
})();

(function(){
  // ── Inject CSS ──
  var sty=document.createElement('style');
  sty.textContent=`
    .sg-loc-overlay{position:fixed;inset:0;z-index:99999;display:flex;align-items:flex-end;justify-content:center;background:rgba(0,0,0,.6);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);opacity:0;transition:opacity .2s ease;pointer-events:none}
    .sg-loc-overlay.open{opacity:1;pointer-events:auto}
    .sg-loc-popup{width:100%;max-width:420px;background:#1a1d27;border-radius:20px 20px 0 0;padding:28px 24px env(safe-area-inset-bottom,24px);transform:translateY(100%);transition:transform .25s cubic-bezier(.32,.72,.32,1)}
    .sg-loc-overlay.open .sg-loc-popup{transform:translateY(0)}
    .sg-loc-icon{text-align:center;margin-bottom:16px}
    .sg-loc-icon-circle{display:inline-flex;align-items:center;justify-content:center;width:56px;height:56px;border-radius:50%;background:rgba(255,109,0,.12);border:2px solid rgba(255,109,0,.25)}
    .sg-loc-icon-circle svg{width:28px;height:28px;fill:none;stroke:#FF6D00;stroke-width:2}
    .sg-loc-title{color:#fff;font-size:18px;font-weight:700;text-align:center;margin-bottom:8px}
    .sg-loc-desc{color:rgba(255,255,255,.5);font-size:14px;text-align:center;line-height:1.5;margin-bottom:24px}
    .sg-loc-options{display:flex;flex-direction:column;gap:8px;margin-bottom:16px}
    .sg-loc-option{display:flex;align-items:center;gap:14px;padding:14px 16px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);border-radius:14px;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:all .15s}
    .sg-loc-option:active{background:rgba(255,255,255,.08);transform:scale(.98)}
    .sg-loc-option.primary{background:rgba(255,109,0,.1);border-color:rgba(255,109,0,.3)}
    .sg-loc-option-icon{font-size:22px;width:40px;height:40px;background:rgba(255,255,255,.06);border-radius:12px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
    .sg-loc-option.primary .sg-loc-option-icon{background:rgba(255,109,0,.15)}
    .sg-loc-option-text{flex:1}
    .sg-loc-option-text strong{color:#fff;font-size:15px;font-weight:600;display:block}
    .sg-loc-option-text span{color:rgba(255,255,255,.4);font-size:12px}
    .sg-loc-option.primary .sg-loc-option-text strong{color:#FF6D00}
    .sg-loc-option .sg-loc-arrow{color:rgba(255,255,255,.2);font-size:18px}
    .sg-loc-cancel{text-align:center;padding:12px;color:rgba(255,255,255,.4);font-size:14px;font-weight:600;cursor:pointer;-webkit-tap-highlight-color:transparent}
    .sg-loc-cancel:active{color:#fff}
  `;
  document.head.appendChild(sty);

  var popupEl=null;

  function _buildPopup(){
    var el=document.createElement('div');
    el.className='sg-loc-overlay';
    el.id='sg-loc-error-popup';
    el.innerHTML=`
      <div class="sg-loc-popup">
        <div class="sg-loc-icon">
          <div class="sg-loc-icon-circle">
            <svg viewBox="0 0 24 24"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z" stroke-linejoin="round"/><circle cx="12" cy="9" r="2.5"/></svg>
          </div>
        </div>
        <div class="sg-loc-title">Location is turned off</div>
        <div class="sg-loc-desc">Enable location to find gyms near you instantly. You can also search by city name instead.</div>
        <div class="sg-loc-options">
          <div class="sg-loc-option primary" onclick="window._sgLocOpenSettings()">
            <div class="sg-loc-option-icon">⚙️</div>
            <div class="sg-loc-option-text">
              <strong>Open Location Settings</strong>
              <span>Enable GPS for precise results</span>
            </div>
            <div class="sg-loc-arrow">›</div>
          </div>
          <div class="sg-loc-option" onclick="window._sgLocSearchInstead()">
            <div class="sg-loc-option-icon">🔍</div>
            <div class="sg-loc-option-text">
              <strong>Search by city instead</strong>
              <span>Type a city or area name</span>
            </div>
            <div class="sg-loc-arrow">›</div>
          </div>
        </div>
        <div class="sg-loc-cancel" onclick="window._sgLocDismiss()">Not now</div>
      </div>
    `;
    // Tap overlay background to dismiss
    el.addEventListener('click',function(e){
      if(e.target===el)window._sgLocDismiss();
    });
    document.body.appendChild(el);
    popupEl=el;
  }

  function _showPopup(){
    if(!popupEl)_buildPopup();
    requestAnimationFrame(function(){
      requestAnimationFrame(function(){
        popupEl.classList.add('open');
      });
    });
    if(navigator.vibrate)navigator.vibrate(30);
  }

  window._sgLocDismiss=function(){
    if(popupEl)popupEl.classList.remove('open');
  };

  window._sgLocOpenSettings=function(){
    window._sgLocDismiss();
    // On Android Chrome, this opens location settings
    // On iOS Safari, we guide user (iOS can't deep-link to settings from web)
    var isIOS=/iPad|iPhone|iPod/.test(navigator.userAgent);
    if(isIOS){
      // iOS: Can't open settings directly from web — show toast with instructions
      if(typeof sgToast==='function'){
        sgToast('📍 Go to Settings → Privacy → Location Services → Safari → Allow','info',5000);
      }
    }else{
      // Android: Try to open location settings via intent
      // This works on Android Chrome — opens device location settings
      try{
        window.open('intent://settings/location#Intent;scheme=android.settings;end','_blank');
      }catch(e){}
      // Fallback toast
      if(typeof sgToast==='function'){
        sgToast('📍 Open your phone Settings → Location → Turn on','info',4000);
      }
    }
  };

  window._sgLocSearchInstead=function(){
    window._sgLocDismiss();
    // Open the search overlay
    if(typeof window._openSearchOverlay==='function'){
      window._openSearchOverlay();
    }
  };

  // ── HOOK: Wrap findGyms to detect denied GPS and show popup ──
  // This does NOT modify findGyms — it wraps it. The original always runs.
  var _origFindGyms=window.findGyms;
  window.findGyms=function(){
    // Always call original first — it has its own fallbacks and never blocks
    _origFindGyms.apply(this,arguments);

    // Then check permission state — if denied, show the popup
    if(navigator.permissions&&navigator.permissions.query){
      navigator.permissions.query({name:'geolocation'}).then(function(status){
        if(status.state==='denied'){
          // Small delay so the app renders first, then popup slides up
          setTimeout(function(){_showPopup();},300);
        }
      }).catch(function(){});
    }
  };

  // ── Also show popup if GPS watch returns error with PERMISSION_DENIED ──
  // Listen for the _fireGPS error without modifying it — we hook into
  // the geolocation error event by monkey-patching watchPosition's error callback.
  // Actually, we DON'T do this — it would modify existing code behavior.
  // Instead, we rely on the permission check in the findGyms wrapper above.
  // This keeps the existing code 100% untouched.
})();
